114	// ──────────────────────────────────────────────────────────────────────────
115	//  Registry views
116	// ──────────────────────────────────────────────────────────────────────────
117	
118	function getRegistry(orgModule) {
119	  const reg = orgModule.loadRegistry();
120	  const agents = Object.values(reg.agents || {});
121	  // Sort: by department, then by level desc, then by name
122	  agents.sort((a, b) => {
123	    if (a.department !== b.department) return (a.department || '').localeCompare(b.department || '');
124	    if ((b.level || 0) !== (a.level || 0)) return (b.level || 0) - (a.level || 0);
125	    return a.id.localeCompare(b.id);
126	  });
127	  return {
128	    version: reg.version || 1,
129	    updatedAt: reg.updatedAt,
130	    total: agents.length,
131	    agents,
132	  };
133	}
