135	function getAgentProfile(orgModule, agentId) {
136	  const record = orgModule.findAgent(agentId);
137	  if (!record) return null;
138	  // Enrich with direct reports + manager
139	  const reports = orgModule.findDirectReports(agentId);
140	  return {
141	    ...record,
142	    directReports: reports.map((r) => ({ id: r.id, title: r.title, level: r.level })),
143	  };
144	}
