146	// ──────────────────────────────────────────────────────────────────────────
147	//  Witness operations — accountability log
148	// ──────────────────────────────────────────────────────────────────────────
149	
150	function logWitnessEvent({ agent, runId, classification, meta = {} }) {
151	  const entry = {
152	    t: new Date().toISOString(),
153	    agent,
154	    runId: runId || null,
155	    class: classification,
156	    ...meta,
157	  };
158	  compactJsonlIfNeeded(WITNESS_LOG, 10000); // keep ~8,000 most recent entries
159	  appendJsonl(WITNESS_LOG, entry);
160	  return entry;
161	}
162	
163	function getWitnessLog({ agent, days = 30, limit = 500 } = {}) {
164	  const all = readJsonl(WITNESS_LOG);
165	  const cutoff = Date.now() - days * 24 * 60 * 60 * 1000;
166	  let filtered = all.filter((e) => new Date(e.t).getTime() >= cutoff);
167	  if (agent) filtered = filtered.filter((e) => e.agent === agent);
168	  return filtered.slice(-limit);
169	}
170	
171	/**
172	 * Run the daily Witness sweep — classify recent runs, detect antipatterns,
173	 * compute daily scores, generate PIP/promotion recommendations.
174	 *
175	 * @param {object} orgModule    — src/org.js
176	 * @param {object} experienceModule — src/experience.js
177	 * @param {array}  agentRuns    — last 24h of agent-runs.json entries
178	 */
179	function runWitnessSweep(orgModule, experienceModule, agentRuns) {
180	  const startedAt = new Date().toISOString();
181	  const registry = orgModule.loadRegistry();
182	  const agents = registry.agents || {};
183	
184	  // 1. Classify each run in the window
185	  const cutoff = Date.now() - 24 * 60 * 60 * 1000;
186	  const recent = agentRuns.filter((r) => new Date(r.timestamp).getTime() >= cutoff);
187	  const classified = [];
188	
189	  for (const run of recent) {
190	    let classification = 'SUCCESS';
191	    if (run.status === 'failed' || run.status === 'error' || run.error) {
192	      classification = 'FAILURE';
193	    } else if (run.duration && run.duration > 600000) {
194	      classification = 'TIMEOUT';
195	    } else if (run.status === 'success') {
196	      classification = 'SUCCESS';
197	    } else {
198	      classification = 'UNCLASSIFIED';
199	    }
200	    const entry = logWitnessEvent({
201	      agent: run.agentName,
202	      runId: run.id,
203	      classification,
204	      meta: {
205	        durationMs: run.duration,
206	        taskType: run.taskType || 'general',
207	        project: run.metadata?.projectId || null,
208	      },
209	    });
210	    classified.push(entry);
211	  }
212	
213	  // 2. Compute daily scores
214	  const scoresByAgent = {};
215	  for (const entry of classified) {
216	    if (!scoresByAgent[entry.agent]) {
217	      scoresByAgent[entry.agent] = { agent: entry.agent, success: 0, failure: 0, antipattern: 0, regression: 0, score: 0 };
218	    }
219	    const s = scoresByAgent[entry.agent];
220	    if (entry.class === 'SUCCESS') s.success++;
221	    else if (entry.class === 'FAILURE' || entry.class === 'TIMEOUT') s.failure++;
222	    else if (entry.class === 'ANTIPATTERN') s.antipattern++;
223	    else if (entry.class === 'REGRESSION') s.regression++;
224	  }
225	  compactJsonlIfNeeded(DAILY_SCORES, 5000); // keep ~4,000 most recent entries
226	  for (const s of Object.values(scoresByAgent)) {
227	    s.score = s.success * 1 - s.failure * 1 - s.antipattern * 2 - s.regression * 3;
228	    s.date = new Date().toISOString().slice(0, 10);
229	    appendJsonl(DAILY_SCORES, s);
230	  }
231	
232	  // 3. Generate PIP + promotion recommendations
233	  const pipCandidates = [];
234	  const promotionCandidates = [];
235	
236	  for (const id of Object.keys(agents)) {
237	    const a = agents[id];
238	    if (a.status === 'retired' || a.status === 'pip') continue;
239	
240	    const stats = a.stats || {};
241	    const successRate = stats.successRate ?? 1;
242	    const antipatterns = stats.antipatternsTriggered || 0;
243	
244	    // PIP triggers
245	    if (stats.totalRuns >= 20 && successRate < 0.7) {
246	      pipCandidates.push({
247	        agent: id,
248	        reasons: [`Success rate ${Math.round(successRate * 100)}%`],
249	        severity: successRate < 0.5 ? 'high' : 'medium',
250	      });
251	    } else if (antipatterns >= 3) {
252	      pipCandidates.push({
253	        agent: id,
254	        reasons: [`${antipatterns} antipatterns triggered`],
255	        severity: 'medium',
256	      });
257	    }
258	
259	    // Promotion eligibility — level crossed threshold, success rate high, 30+ days at level
260	    if (a.level != null && a.level < 8 && successRate >= 0.85 && antipatterns === 0) {
261	      const needsRuns = a.level >= 3 ? (stats.patternsContributed || 0) >= 1 : true;
262	      if (needsRuns) {
263	        promotionCandidates.push({
264	          agent: id,
265	          fromLevel: a.level,
266	          toLevel: a.level + 1,
267	          fromTitle: a.levelTitle,
268	          signals: [
269	            `${a.yearsOfExperience} YoE`,
270	            `${Math.round(successRate * 100)}% success`,
271	            `${stats.patternsContributed || 0} patterns`,
272	            `${antipatterns} antipatterns`,
273	          ],
274	        });
275	      }
276	    }
277	  }
278	
279	  const recommendations = {
280	    generatedAt: startedAt,
281	    completedAt: new Date().toISOString(),
282	    runsClassified: classified.length,
283	    pipCandidates,
284	    promotionCandidates,
285	  };
286	  writeJson(RECOMMENDATIONS, recommendations);
287	
288	  return recommendations;
289	}
