330	function openPip(orgModule, agentId, reason) {
331	  const record = orgModule.findAgent(agentId);
332	  if (!record) return { ok: false, error: 'Agent not found' };
333	  if (record.status === 'pip') return { ok: false, error: 'Already on PIP' };
334	
335	  const deadline = new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString();
336	  const updated = orgModule.upsertAgent(agentId, {
337	    status: 'pip',
338	    pip: {
339	      openedAt: new Date().toISOString(),
340	      deadline,
341	      reason: reason || 'Performance below threshold',
342	      openedBy: 'cadence',
343	    },
344	  });
345	
346	  logWitnessEvent({ agent: agentId, classification: 'PIP_OPENED', meta: { deadline, reason } });
347	  return { ok: true, agent: updated };
348	}
