350	function closePip(orgModule, agentId, outcome) {
351	  const record = orgModule.findAgent(agentId);
352	  if (!record) return { ok: false, error: 'Agent not found' };
353	  if (record.status !== 'pip') return { ok: false, error: 'Not on PIP' };
354	
355	  const updated = orgModule.upsertAgent(agentId, {
356	    status: outcome === 'pass' ? 'active' : 'retired',
357	    pip: { ...record.pip, closedAt: new Date().toISOString(), outcome },
358	  });
359	
360	  logWitnessEvent({ agent: agentId, classification: 'PIP_CLOSED', meta: { outcome } });
361	  return { ok: true, agent: updated };
362	}
