364	function retireAgent(orgModule, agentId, reason) {
365	  const record = orgModule.findAgent(agentId);
366	  if (!record) return { ok: false, error: 'Agent not found' };
367	
368	  const updated = orgModule.upsertAgent(agentId, {
369	    status: 'retired',
370	    retiredAt: new Date().toISOString(),
371	    retiredReason: reason || 'No longer in active rotation',
372	  });
373	
374	  logWitnessEvent({ agent: agentId, classification: 'RETIRED', meta: { reason } });
375	  return { ok: true, agent: updated };
376	}
