378	function unretireAgent(orgModule, agentId) {
379	  const record = orgModule.findAgent(agentId);
380	  if (!record) return { ok: false, error: 'Agent not found' };
381	  if (record.status !== 'retired') return { ok: false, error: 'Not retired' };
382	
383	  const updated = orgModule.upsertAgent(agentId, {
384	    status: 'active',
385	    retiredAt: null,
386	    retiredReason: null,
387	  });
388	
389	  logWitnessEvent({ agent: agentId, classification: 'UNRETIRED' });
390	  return { ok: true, agent: updated };
391	}
