397	function hireAgent(orgModule, { id, name, department, phase, reportsTo, title, tier, role, description }) {
398	  if (!id || !department) return { ok: false, error: 'id and department are required' };
399	
400	  const existing = orgModule.findAgent(id);
401	  if (existing) return { ok: false, error: 'Agent already exists' };
402	
403	  const now = new Date().toISOString();
404	  const record = orgModule.upsertAgent(id, {
405	    id,
406	    name: name || id,
407	    description: description || '',
408	    department,
409	    phase: phase || null,
410	    reportsTo: reportsTo || 'cadence',
411	    title: title || 'New Hire',
412	    tier: tier || 'engineer',
413	    role: role || null,
414	    hiredAt: now,
415	    status: 'probation',
416	    level: 0,
417	    levelTitle: 'Trainee',
418	    yearsOfExperience: 0,
419	    experiencePoints: 0,
420	  });
421	
422	  // Create onboarding checklist
423	  const checklistPath = path.join(ONBOARDING_DIR, `${id}.json`);
424	  writeJson(checklistPath, {
425	    agent: id,
426	    hiredAt: now,
427	    stage: 'probation',
428	    runsRequired: 10,
429	    runsCompleted: 0,
430	    steps: [
431	      { id: 'create_md', done: false, label: 'Agent .md file exists on disk' },
432	      { id: 'load_memory', done: false, label: 'Memory brain loaded into first run' },
433	      { id: 'shadow_3', done: false, label: 'First 3 runs shadowed by senior agent' },
434	      { id: 'independent_7', done: false, label: '7 independent runs with Witness watching' },
435	      { id: 'probation_review', done: false, label: 'Cadence probationary review' },
436	    ],
437	    createdAt: now,
438	  });
439	
440	  logWitnessEvent({ agent: id, classification: 'HIRED', meta: { department, reportsTo } });
441	  return { ok: true, agent: record };
442	}
