444	// ──────────────────────────────────────────────────────────────────────────
445	//  Training queue
446	// ──────────────────────────────────────────────────────────────────────────
447	
448	function getTrainingQueue() {
449	  return readJson(TRAINING_QUEUE, { version: 1, updatedAt: null, items: [] });
450	}
451	
452	function queueTraining({ agent, skill, reason, priority = 'medium' }) {
453	  const queue = getTrainingQueue();
454	  queue.items = queue.items || [];
455	  queue.items.push({
456	    id: `train-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
457	    agent,
458	    skill,
459	    reason,
460	    priority,
461	    status: 'pending',
462	    queuedAt: new Date().toISOString(),
463	  });
464	  queue.updatedAt = new Date().toISOString();
465	  writeJson(TRAINING_QUEUE, queue);
466	  return queue;
467	}
468	
469	function completeTraining(itemId, outcome = 'passed') {
470	  const queue = getTrainingQueue();
471	  const item = (queue.items || []).find((i) => i.id === itemId);
472	  if (!item) return { ok: false, error: 'Item not found' };
473	  item.status = outcome === 'passed' ? 'completed' : 'failed';
474	  item.completedAt = new Date().toISOString();
475	  queue.updatedAt = new Date().toISOString();
476	  writeJson(TRAINING_QUEUE, queue);
477	  return { ok: true, item };
478	}
