480	// ──────────────────────────────────────────────────────────────────────────
481	//  Capability gap detection
482	// ──────────────────────────────────────────────────────────────────────────
483	
484	/**
485	 * Given a brief (natural language task description), find out if the
486	 * current roster can handle it. Uses simple keyword matching against
487	 * each agent's skill vector from registry.json.
488	 */
489	function detectCapabilityGap(orgModule, brief, requiredSkillsHint = []) {
490	  const registry = orgModule.loadRegistry();
491	  const agents = Object.values(registry.agents || {})
492	    .filter((a) => a.status === 'active' || a.status === 'probation');
493	
494	  // Infer required skills from brief text if not explicitly given
495	  const inferredSkills = new Set(requiredSkillsHint);
496	  const briefLower = (brief || '').toLowerCase();
497	  const SKILL_HINTS = {
498	    react: ['react', 'component', 'frontend', 'ui'],
499	    typescript: ['typescript', 'ts'],
500	    nextjs: ['next.js', 'app router'],
501	    supabase: ['supabase', 'postgres', 'rls'],
502	    shopify: ['shopify', 'storefront', 'polaris'],
503	    billing: ['stripe', 'billing', 'subscription', 'payment', 'dodo'],
504	    auth: ['auth', 'oauth', 'session', 'login', 'sign in'],
505	    testing: ['test', 'vitest', 'playwright'],
506	    design: ['design', 'figma', 'ui/ux'],
507	    seo: ['seo', 'sitemap', 'meta'],
508	    deployment: ['deploy', 'railway', 'docker'],
509	    ai: ['llm', 'gpt', 'claude', 'prompt'],
510	    marketing: ['landing', 'copy', 'funnel', 'email'],
511	    research: ['validate', 'icp', 'interview', 'market'],
512	    debugging: ['bug', 'fix', 'error', 'crash'],
513	    architecture: ['architecture', 'system design', 'scalab'],
514	  };
515	  for (const [skill, hints] of Object.entries(SKILL_HINTS)) {
516	    if (hints.some((h) => briefLower.includes(h))) inferredSkills.add(skill);
517	  }
518	
519	  const required = [...inferredSkills];
520	  if (required.length === 0) {
521	    return {
522	      canHandle: true,
523	      confidence: 0.5,
524	      bestMatches: [],
525	      gaps: [],
526	      recommendation: 'proceed',
527	      note: 'No specific skills inferred from brief',
528	      inferredSkills: [],
529	    };
530	  }
531	
532	  // Score each agent against required skills
533	  const scored = agents.map((a) => {
534	    const skills = a.skills || {};
535	    let totalScore = 0;
536	    const matched = [];
537	    const missing = [];
538	    for (const req of required) {
539	      const s = skills[req]?.score || 0;
540	      if (s > 0) matched.push({ skill: req, score: s });
541	      else missing.push(req);
542	      totalScore += s;
543	    }
544	    return {
545	      agent: a.id,
546	      title: a.title,
547	      level: a.level,
548	      score: Math.round((totalScore / required.length) * 100) / 100,
549	      matched,
550	      missing,
551	    };
552	  });
553	
554	  scored.sort((a, b) => b.score - a.score);
555	  const bestMatches = scored.slice(0, 3);
556	
557	  // Determine gap + recommendation
558	  const topScore = bestMatches[0]?.score || 0;
559	  const allMissing = required.filter((r) => !scored.some((s) => s.matched.find((m) => m.skill === r && m.score >= 0.4)));
560	  const canHandle = topScore >= 0.7 && allMissing.length === 0;
561	
562	  let recommendation;
563	  if (canHandle) recommendation = 'proceed';
564	  else if (topScore >= 0.4) recommendation = `train-${bestMatches[0].agent}`;
565	  else recommendation = 'hire';
566	
567	  // Log the gap (compact if needed)
568	  compactJsonlIfNeeded(CAPABILITY_GAPS, 2000); // keep ~1,600 most recent entries
569	  appendJsonl(CAPABILITY_GAPS, {
570	    t: new Date().toISOString(),
571	    brief: brief.slice(0, 200),
572	    inferredSkills: required,
573	    gaps: allMissing,
